Method.Source:
    // MPJ-21310

    /// <summary>
    /// Check if this entry is already referenced on a sales order line.
    /// </summary>
    /// <returns>Result</returns>
    public boolean salesLineExists()
    {
        METSalesLine   metSalesLine;
        select firstonly RecId from metSalesLine
            where   metSalesLine.SubstitutionType           == METSalesItemSubstitutionType::ParentChild
            &&      metSalesLine.SubstitutionSetupRefRecID  == this.RecId;
        return metSalesLine.RecID != 0;
    }

/// <summary>
/// validateWrite
/// </summary>
/// <returns>Result</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(ret)
    {
        METSalesItemSubstitutionParentChild otherParentChild;
        select firstonly RecId from otherParentChild
            where   otherParentChild.ParentItemID   == this.ChildItemID
            &&      otherParentChild.InventSiteId   == this.InventSiteId
            &&      otherParentChild.RecId          != 0;
        if(otherParentChild)
        {
            ret = checkFailed(strFmt("@MET:SubChildExistsAsParentError",
                this.ChildItemID));
        }
        select firstonly RecId from otherParentChild
            where   otherParentChild.ChildItemID    == this.ParentItemID
            &&      otherParentChild.InventSiteId   == this.InventSiteId
            &&      otherParentChild.RecId          != 0;
        if(otherParentChild)
        {
            ret = checkFailed(strFmt("@MET:SubParentExistsAsChildError",
                this.ParentItemID));
        }
    }
    return ret;
}

    /// <summary>
    /// validateDelete
    /// </summary>
    /// <returns>Result</returns>
    public boolean validateDelete()
    {
        boolean ret;
    
        ret = super();
    
        if(ret)
        {
            if(this.salesLineExists())
            {
                ret = checkFailed("@MET:SubCannotDeleteOrModifyExistsSalesLine");
            }
        }

        return ret;
    }

/// <summary>
/// Record description, mainly used for tracing/logging.
/// </summary>
/// <returns>Description</returns>
public str description()
{
    return strFmt('Child %1, Parent %2, Site %3',
        this.ChildItemID,
        this.ParentItemID,
        this.InventSiteId);
}

    /// <summary>
    /// validateField
    /// </summary>
    /// <param name = "_fieldIdToCheck">field id</param>
    /// <returns>True if validated</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch(_fieldIdToCheck)
        {
            case fieldNum(METSalesItemSubstitutionParentChild, ParentItemId):
                ret = METSalesItemSubstitute::itemIDCanBeSelected(this.ParentItemID, this.InventSiteId) && ret;
                break;
            case fieldNum(METSalesItemSubstitutionParentChild, ChildItemID):
                ret = METSalesItemSubstitute::itemIDCanBeSelected(this.ChildItemID, this.InventSiteId) && ret;
                break;
        }
        return ret;
    }
